/*
 * SPDX-License-Identifier: BSD-2-Clause
 * Copyright 2026 amigazen project
 *
 * btree_avl.c - AVL balanced binary tree operations
 */

#include <exec/types.h>
#include "private/bt_intern.h"

static LONG bt_AVL_Height(struct BTNode *node)
{
    ULONG leftHeight;
    ULONG rightHeight;

    if (node == NULL) {
        return 0;
    }
    leftHeight = bt_CalculateHeight(node->bn_Left);
    rightHeight = bt_CalculateHeight(node->bn_Right);
    if (leftHeight > rightHeight) {
        return (LONG)leftHeight;
    }
    return (LONG)rightHeight;
}

static LONG bt_AVL_GetBalance(struct BTNode *node)
{
    LONG leftHeight;
    LONG rightHeight;

    if (node == NULL) {
        return BT_AVL_BALANCED;
    }
    leftHeight = bt_AVL_Height(node->bn_Left);
    rightHeight = bt_AVL_Height(node->bn_Right);
    return leftHeight - rightHeight;
}

static void bt_AVL_SetChild(struct BTTree *tree, struct BTNode *parent,
    struct BTNode *oldChild, struct BTNode *newChild)
{
    if (parent == NULL) {
        tree->bt_Root = newChild;
        return;
    }
    if (parent->bn_Left == oldChild) {
        parent->bn_Left = newChild;
    } else {
        parent->bn_Right = newChild;
    }
}

static struct BTNode *bt_AVL_RotateLeft(struct BTTree *tree, struct BTNode *node)
{
    struct BTNode *rightChild;

    rightChild = node->bn_Right;
    if (rightChild == NULL) {
        return node;
    }

    node->bn_Right = rightChild->bn_Left;
    if (rightChild->bn_Left != NULL) {
        rightChild->bn_Left->bn_Parent = node;
    }

    rightChild->bn_Parent = node->bn_Parent;
    bt_AVL_SetChild(tree, node->bn_Parent, node, rightChild);

    rightChild->bn_Left = node;
    node->bn_Parent = rightChild;
    return rightChild;
}

static struct BTNode *bt_AVL_RotateRight(struct BTTree *tree, struct BTNode *node)
{
    struct BTNode *leftChild;

    leftChild = node->bn_Left;
    if (leftChild == NULL) {
        return node;
    }

    node->bn_Left = leftChild->bn_Right;
    if (leftChild->bn_Right != NULL) {
        leftChild->bn_Right->bn_Parent = node;
    }

    leftChild->bn_Parent = node->bn_Parent;
    bt_AVL_SetChild(tree, node->bn_Parent, node, leftChild);

    leftChild->bn_Right = node;
    node->bn_Parent = leftChild;
    return leftChild;
}

static struct BTNode *bt_AVL_Rebalance(struct BTTree *tree, struct BTNode *node)
{
    LONG balance;
    LONG leftBalance;
    LONG rightBalance;

    while (node != NULL) {
        balance = bt_AVL_GetBalance(node);
        if (balance > 1) {
            rightBalance = bt_AVL_GetBalance(node->bn_Right);
            if (rightBalance < 0) {
                bt_AVL_RotateRight(tree, node->bn_Right);
            }
            node = bt_AVL_RotateLeft(tree, node);
            node = node->bn_Parent;
        } else if (balance < -1) {
            leftBalance = bt_AVL_GetBalance(node->bn_Left);
            if (leftBalance > 0) {
                bt_AVL_RotateLeft(tree, node->bn_Left);
            }
            node = bt_AVL_RotateRight(tree, node);
            node = node->bn_Parent;
        } else {
            node = node->bn_Parent;
        }
    }
    return tree->bt_Root;
}

struct BTNode *bt_AVL_Find(struct BTTree *tree, CONST_APTR key)
{
    struct BTNode *current;
    LONG cmp;

    current = tree->bt_Root;
    while (current != NULL) {
        cmp = tree->bt_Args.Compare(tree->bt_Args.UserData, key, current->bn_Key);
        if (cmp == 0) {
            return current;
        }
        if (cmp < 0) {
            current = current->bn_Left;
        } else {
            current = current->bn_Right;
        }
    }
    return NULL;
}

struct BTNode *bt_AVL_Insert(struct BTTree *tree, CONST_APTR key, CONST_APTR data)
{
    struct BTNode *newNode;
    struct BTNode *parent;
    struct BTNode *current;
    LONG cmp;

    newNode = bt_CreateNode(tree, key, data);
    if (newNode == NULL) {
        return NULL;
    }

    parent = NULL;
    current = tree->bt_Root;
    while (current != NULL) {
        parent = current;
        cmp = tree->bt_Args.Compare(tree->bt_Args.UserData, key, current->bn_Key);
        if (cmp < 0) {
            current = current->bn_Left;
        } else {
            current = current->bn_Right;
        }
    }

    newNode->bn_Parent = parent;
    if (parent == NULL) {
        tree->bt_Root = newNode;
    } else {
        cmp = tree->bt_Args.Compare(tree->bt_Args.UserData, key, parent->bn_Key);
        if (cmp < 0) {
            parent->bn_Left = newNode;
        } else {
            parent->bn_Right = newNode;
        }
    }

    bt_AVL_Rebalance(tree, newNode);
    tree->bt_Size++;
    bt_UpdateHeight(tree);
    return newNode;
}

static void bt_AVL_DeleteLeaf(struct BTTree *tree, struct BTNode *node)
{
    struct BTNode *parent;
    struct BTNode *child;

    parent = node->bn_Parent;
    child = NULL;

    if (node->bn_Left == NULL && node->bn_Right == NULL) {
        bt_AVL_SetChild(tree, parent, node, NULL);
    } else if (node->bn_Left == NULL || node->bn_Right == NULL) {
        child = node->bn_Left;
        if (child == NULL) {
            child = node->bn_Right;
        }
        child->bn_Parent = parent;
        bt_AVL_SetChild(tree, parent, node, child);
    }

    bt_DestroyNode(tree, node);
    if (parent != NULL) {
        bt_AVL_Rebalance(tree, parent);
    }
    tree->bt_Size--;
    bt_UpdateHeight(tree);
}

void bt_AVL_Delete(struct BTTree *tree, struct BTNode *node)
{
    struct BTNode *successor;

    if (tree == NULL || node == NULL) {
        return;
    }

    if (node->bn_Left != NULL && node->bn_Right != NULL) {
        successor = bt_FindSuccessor(node);
        bt_SwapNodePayload(node, successor);
        node = successor;
    }

    bt_AVL_DeleteLeaf(tree, node);
}

